"""Format the retained 30-checkpoint K050 latency ablations for the appendix."""

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
SOURCE = HERE / "investigation/data/checkpoints.json"


def main():
    rows = json.loads(SOURCE.read_text(encoding="utf-8"))
    assert [row["condition"] for row in rows] == [f"c{i:02d}" for i in range(1, 31)]
    fields = ("native_baseline_gm_ms", "all_skips_off_candidate_gm_ms",
              "projection_on_candidate_gm_ms", "full_candidate_gm_ms")
    lines = [
        "% Generated by Analysis 021 / 08_kernel_manuscript_table.py.",
        "% Source: investigation/data/checkpoints.json; observation O001-kernel-investigation.md.",
        r"\begin{tabular}{@{}llrrrrr@{}}",
        r"\toprule",
        r"ID & Recipe & $\lambda/\kappa$ & Native & All skips off & Proj. only & Full K050 \\",
        r"\midrule",
    ]
    for i, row in enumerate(rows):
        if i and row["recipe"] != rows[i - 1]["recipe"]:
            lines.append(r"\addlinespace[2pt]")
        dose = row["kappa"] if row["kappa"] is not None else row["pressure_weight"]
        if row["recipe"] in ("A0", "A1-H"):
            dose = None
        dose_text = "--" if dose is None else f"{dose:g}"
        values = [row["condition"], row["recipe"], dose_text]
        values.extend(f"{row[field]:.5f}" for field in fields)
        lines.append(" & ".join(values) + r" \\")
    lines.extend([r"\bottomrule", r"\end{tabular}", ""])
    output = HERE / "tables/kernel-checkpoint-latencies.tex"
    output.parent.mkdir(exist_ok=True)
    output.write_text("\n".join(lines), encoding="utf-8", newline="\n")
    print(f"Wrote {len(rows)} checkpoint rows to {output.relative_to(HERE)}")


if __name__ == "__main__":
    main()
